        <dl className="grid grid-cols-2 gap-3">
          <div className={cn("rounded-2xl p-3", dunkel ? "bg-white/[0.06]" : "bg-sand-50")}>
            <dt className={cn("flex items-center gap-1.5 text-[12px]", sub)}>
              <Sun aria-hidden="true" className="h-3.5 w-3.5 text-sun-400" /> Solar
            </dt>
            <dd className={cn("mt-1 font-display text-[19px] font-extrabold", text)}>{e?.solarMw != null ? `${fmtGw(e.solarMw)} GW` : "–"}</dd>
          </div>
          <div className={cn("rounded-2xl p-3", dunkel ? "bg-white/[0.06]" : "bg-sand-50")}>
            <dt className={cn("flex items-center gap-1.5 text-[12px]", sub)}>
              <Leaf aria-hidden="true" className="h-3.5 w-3.5 text-ov-400" /> Erneuerbare
            </dt>
            <dd className={cn("mt-1 font-display text-[19px] font-extrabold", text)}>{e?.eeAnteil != null ? `${Math.round(e.eeAnteil)} %` : "–"}</dd>
