// node teile.mjs <pfad> <breite> <name> [teilHoehe] [aktion-js]
// Ganze Seite in Kacheln (je teilHoehe px) speichern + horizontalen Überlauf melden
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const [pfad, breite = "1440", name = "x", th = "1800", aktion] = process.argv.slice(2);
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: +breite, height: 900 }, deviceScaleFactor: 1 });
const fehler = [];
p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 300)));
const r = await p.goto("http://localhost:3100" + pfad, { waitUntil: "networkidle", timeout: 120000 });
await p.evaluate(() => document.querySelectorAll(".ov-reveal").forEach((e) => e.classList.add("is-visible")));
if (aktion) { await p.evaluate(aktion); await p.waitForTimeout(800); }
await p.waitForTimeout(1000);
const H = await p.evaluate(() => document.documentElement.scrollHeight);
const ueber = await p.evaluate(() => { const w = document.documentElement.clientWidth; return [...document.querySelectorAll("body *")].filter(e => { const r = e.getBoundingClientRect(); return r.right > w + 1 && r.width > 0; }).slice(0, 8).map(e => e.tagName + "." + String(e.className).slice(0, 60) + " r=" + Math.round(e.getBoundingClientRect().right)); });
const sw = await p.evaluate(() => document.documentElement.scrollWidth);
let n = 0;
for (let y = 0; y < H; y += +th) {
  const h = Math.min(+th, H - y);
  await p.screenshot({ path: fileURLToPath(new URL(`./shots/${name}_${breite}_${n}.png`, import.meta.url)), fullPage: true, clip: { x: 0, y, width: +breite, height: h } });
  n++;
}
console.log(r.status(), `H=${H} teile=${n} scrollWidth=${sw}`, ueber.length ? "\nÜBERLAUF:\n" + ueber.join("\n") : "", fehler.length ? "\n" + fehler.join("\n") : "");
await b.close();
EOF
