            <Zahl wert={r.gesamt.eurMin} /> – <Zahl wert={r.gesamt.eurMax} suffix=" €" />
          </Kennzahl>
          <Kennzahl label="je kWh Reststrom" icon={Zap} zusatz={`${fmt(r.gesamt.anteilMin * 100, 0)}–${fmt(r.gesamt.anteilMax * 100, 0)} % der Stromkosten`}>
