export default function LaenderTabs() {
  const [aktiv, setAktiv] = useState("de");
  const basis = useId();
  const refs = useRef({});
  const land = LAENDER.find((l) => l.id === aktiv);

  const tastatur = (e) => {
    const i = LAENDER.findIndex((l) => l.id === aktiv);
    let n = null;
    if (e.key === "ArrowRight") n = (i + 1) % LAENDER.length;
    if (e.key === "ArrowLeft") n = (i - 1 + LAENDER.length) % LAENDER.length;
    if (e.key === "Home") n = 0;
    if (e.key === "End") n = LAENDER.length - 1;
    if (n != null) {
      e.preventDefault();
      setAktiv(LAENDER[n].id);
      refs.current[LAENDER[n].id]?.focus();
    }
  };

  return (
    <div>
      <div role="tablist" aria-label="Land wählen" onKeyDown={tastatur} className="grid grid-cols-3 gap-1.5 rounded-2xl bg-white p-1.5 ring-1 ring-ink-200/70 sm:inline-grid">
