          <p className="mt-6 flex gap-3 rounded-2xl bg-sand-50 p-4 text-[14.5px] leading-relaxed text-ink-600 ring-1 ring-ink-200/60">
            <AlertCircle aria-hidden="true" className="mt-0.5 h-5 w-5 shrink-0 text-sun-500" />
            <span>
