 */
export default function GemeinschaftSvg({ className }) {
  const haus = (x, y, s = 1) => (
    <g transform={`translate(${x} ${y}) scale(${s})`}>
      <path d="M0 22 L22 4 L44 22 V52 H0 Z" fill="#ffffff" stroke="#003473" strokeWidth="2" strokeLinejoin="round" />
