              <path key={c} d={`M${c * 30} 0 h26 l-8 18 h-26 z`} fill="#003473" stroke="#4a7cbd" strokeWidth="1" />
            ))}
          </g>
        ))}
        <text x="60" y="108" textAnchor="middle" fontSize="14" fontWeight="700" fill="#151a24">Solarpark</text>
